'use strict';
const root=document.getElementById('app');
const STAGES=[['midnight','01','The Midnight Ticket','Privileged identity compromise, lateral movement and ransomware.','🏰'],['lantern','02','Paper Lantern','Valid API credentials abused for large-scale data theft.','🪙'],['valve','03','The Valve Room','IT-to-OT intrusion with process safety and operational risk.','🏭'],['webshell','04','The Hidden Handler','Webshell detection and cleartext HTTP payload reconstruction.','🕸️']];
const $esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $fmt=t=>`${String(Math.floor((t||0)/60)).padStart(2,'0')}:${String((t||0)%60).padStart(2,'0')}`;
const UI={board:{leaderboard:[],players:0,stages:STAGES.map(x=>x[0])},player:null,game:null,reports:[],reviewStage:null,tab:'operations',filter:'ready',source:'Logs',query:'',modal:null,error:'',notice:'',busy:false,answer:{},adminPassword:'',adminData:null,adminPhrase:'',roundFilter:'all',guideOpen:false,caseTab:'flags',showAllActions:false,showMissionBrief:true,showHistory:false,adminFilter:'all',adminSort:'rank'};
function status(x){return x==='complete'?'✓ Complete':x==='active'?'● In progress':'○ Locked'}
function pill(x,extra=''){return `<span class="pill ${extra}">${$esc(x)}</span>`}
function stage(id){return STAGES.find(x=>x[0]===id)||STAGES[0]}
function label(v){return v==null?'—':v}
async function request(url,body){const opt={credentials:'same-origin',headers:{Accept:'application/json'}};if(body!==undefined){opt.method='POST';opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body)}let resp;try{resp=await fetch(url,opt)}catch(e){throw Error('Competition server is unreachable. Check the server connection.')}let x;try{x=await resp.json()}catch(e){throw Error('Invalid response from competition server')}if(!resp.ok)throw Error(x.error||`Request failed (${resp.status})`);return x;}
async function load(){try{const [board,me]=await Promise.all([request('/api/board'),request('/api/me').catch(e=>e.message.includes('Choose a username')?null:Promise.reject(e))]);UI.board=board;if(me)updateMe(me);render();}catch(e){root.innerHTML=`<div class="boot"><div class="brand-icon">✥</div><h2>Connection unavailable</h2><p>${$esc(e.message)}</p><button class="btn primary spacing" data-act="reload">Retry connection</button></div>`;}}
function updateMe(payload){UI.player=payload.player;UI.game=payload.game;UI.reports=payload.reports||[];if(UI.game){UI.query=UI.game.console?.query||'';UI.source=UI.game.console?.source||'Logs';}if(payload.feedback?.verdict)UI.modal={type:'result',feedback:payload.feedback,coaching:payload.coaching||null,escalations:payload.escalations||[]};if(payload.feedback?.conclusion)UI.notice=payload.feedback.coaching||'';}
function boardRows(limit){const arr=UI.board.leaderboard||[],rows=limit?arr.slice(0,limit):arr;
 return `<div class="leaderboard"><table><thead><tr><th>Rank</th><th>Player</th><th>Midnight</th><th>Lantern</th><th>Valve</th><th>Webshell</th><th>Total / 400</th></tr></thead><tbody>${rows.length?rows.map(p=>`<tr class="${UI.player?.name===p.name?'me':''}"><td class="rank">#${p.rank}</td><td><b>${$esc(p.name)}</b><div class="subtitle">${p.finished?'✓ All missions complete':p.completed+'/4 missions complete'}</div></td>${(p.rounds||[]).map(n=>`<td class="mono">${n===null?'—':n}</td>`).join('')}<td class="pts">${p.score}${p.provisional>0?`<div class="subtitle">${p.finalizedTotal} finalized + ${p.provisional} live</div>`:''}</td></tr>`).join(''):'<tr><td colspan="7" class="muted" style="padding:22px">No players yet. Be the first to enter the arena.</td></tr>'}</tbody></table></div>`;}
function home(){return `<div class="landing"><header class="row"><div class="brand"><div class="brand-icon">✥</div><div><b>THE WAR ROOM</b><small>Live multiplayer CTF • v5 engine</small></div></div>${pill('● LIVE LEADERBOARD','live')}</header><section class="hero"><div><div class="kicker">THE WAR ROOM / INCIDENT RESPONSE CTF</div><h1 class="spacing">Hunt. Contain. <strong>Outscore.</strong></h1><p class="intro">Investigate, contain and learn. Compete against other incident responders across four NetWitness-inspired tabletop scenarios. Everyone investigates independently while the live leaderboard tracks combined mission scores.</p><div class="chips spacing">${pill('Four mandatory scenarios')}${pill('One attempt per stage')}${pill('No account registration')}${pill('Server-verified scoring')}</div></div><div class="hero-card"><div class="micro teal">JOIN THE COMPETITION</div><h2>Choose your callsign</h2><p class="spacing">Pick a unique username to start. Your session is remembered in this browser, with no email or password required.</p><form id="join-form" class="form spacing"><div><label class="label" for="username">Player username</label><input id="username" class="input" name="username" maxlength="24" minlength="3" pattern="[A-Za-z0-9][A-Za-z0-9_-]{2,23}" placeholder="e.g. PacketRanger" autocomplete="nickname" required></div><button class="btn primary full" type="submit" ${UI.busy?'disabled':''}>Join and begin scenario 1 →</button><div class="tiny muted">3–24 characters, letters, numbers, hyphens and underscores. Usernames are unique and cannot be claimed from another browser without the original session cookie.</div>${UI.error?`<div class="alert error">${$esc(UI.error)}</div>`:''}${UI.notice?`<div class="alert">${$esc(UI.notice)}</div>`:''}</form></div></section><section><div class="row" style="margin-bottom:14px"><div><div class="kicker">THE FOUR CHALLENGES</div><h2>One tournament. Four missions.</h2></div>${pill('Standard difficulty for everyone')}</div><div class="grid3">${STAGES.map(s=>`<div class="panel scenario"><div class="num">MISSION ${s[1]} <span style="float:right;font-size:24px">${s[4]}</span></div><h3>${s[2]}</h3><p class="tiny">${s[3]}</p></div>`).join('')}</div></section><section class="panel spacing" id="leaderboard"><div class="title"><div><h2>Live rankings</h2><p>Finalized scores plus provisional points from the active round. Rankings update after every move.</p></div>${pill((UI.board.players||0)+' competitors','live')}</div><div id="board-table">${boardRows(20)}</div></section><div class="footer row"><span>Offline-style NetWitness simulation, hosted for live competition. No connection to actual NetWitness systems.</span><button class="btn small" data-act="admin">Admin controls</button></div></div>`;}
function sidebar(){
 const current=UI.player?.active??-1,done=UI.player?.completed??0,score=UI.player?.liveTotal??UI.player?.total??0;
 const items=[['operations','⚔','Mission'],['telemetry','⌕','Investigation'],['casebook','◇','Casebook'],['leaderboard','♛','Rankings']];
 const currentTab=UI.tab==='evidence'||UI.tab==='hypotheses'||UI.tab==='debrief'?'casebook':UI.tab;
 return `<aside class="sidebar compact-sidebar"><div class="brand"><div class="brand-icon">✥</div><div><b>THE WAR ROOM</b><small>Incident Response · CTF</small></div></div>
 <nav class="nav-list" aria-label="Primary navigation"><div class="nav-label">Workspace</div>${items.map(([id,icon,name])=>`<button class="nav ${currentTab===id?'active':''}" data-act="tab" data-id="${id}"><span>${icon}</span>${name}${id==='casebook'&&UI.game?`<small class="nav-number">${UI.game.evidence?.length||0}</small>`:''}</button>`).join('')}</nav>
 <div class="compact-round"><div class="micro muted">TOURNAMENT • ${done}/4 COMPLETE</div><div class="round-dots">${STAGES.map((item,i)=>`<span class="round-dot ${i<done?'complete':i===current?'active':''}" title="${$esc(item[2])}"></span>`).join('')}</div><p class="tiny muted">${current>=0?`${STAGES[current][1]} · ${STAGES[current][2]}`:'All active missions finished'}</p></div>
 <div class="sidebar-bottom"><div class="compact-account"><b>${$esc(UI.player?.name||'')}</b><span class="tiny muted">#${UI.player?.rank||'—'} · ${score}/400 pts</span></div><button class="nav admin-access" data-act="tab" data-id="admin"><span>⚙</span>Admin settings</button></div>
</aside>`;
}
function metrics(){const r=UI.game?.round;if(!r)return '';return `<div class="metrics compact-metrics" aria-label="Incident status">${[['Clock',$fmt(r.clock),'◷'],['Business',r.health+'%','▣'],['Threat',r.pressure+'%','⚡'],['Exposure',r.exposure+'%','◈']].map(([k,v,i])=>`<div class="metric"><small>${i} ${k}</small><b>${v}</b></div>`).join('')}</div>`;}
function roundBanner(){const r=UI.game?.round;if(!r)return '';return `<div class="mission-header-compact"><div class="mission-title"><div class="kicker">MISSION ${stage(r.id)[1]} / INCIDENT RESPONSE</div><h2>${$esc(r.title)}</h2><p class="tiny muted full-mission-description">${$esc(r.brief)}</p></div><div class="mission-header-actions">${pill(r.ended?'Case ended':'● Incident active',r.ended?'':'live')}<button class="btn small" data-act="brief-toggle">${UI.showMissionBrief?'Hide opening':'Show opening'} ▾</button></div></div>${UI.showMissionBrief?`<div class="alert mission-brief"><b>Initial incident alert:</b> ${$esc(r.opening)}</div>`:''}`;}
function missions(){if(!UI.game)return nextScreen();const g=UI.game;
 const filter=UI.filter;
 const available=g.actions.filter(a=>!a.done&&!a.locked&&a.cat!=='risky');
 const selected=g.actions.filter(a=>filter==='ready'?!a.done&&!a.locked&&a.cat!=='risky':filter==='all'?true:filter==='response'?['contain','coordinate','recover','risky'].includes(a.cat):['investigate','hunt'].includes(a.cat));
 const ordered=selected.slice().sort((a,b)=>Number(a.done)-Number(b.done)||Number(a.locked)-Number(b.locked));
 const shown=UI.showAllActions?ordered:ordered.slice(0,6);
 return `${roundBanner()}<div class="workspace-heading"><div><div class="kicker">YOUR NEXT MOVES</div><h3>${filter==='ready'?'Available actions':filter==='response'?'Containment & response':filter==='investigation'?'Investigative work':'All incident orders'}</h3></div><div class="tiny muted">${available.length} ready · ${g.actions.filter(a=>a.done).length} completed</div></div>
 <div class="mission-layout"><section class="mission-actions"><div class="quick-nav">${[['ready','Ready'],['response','Response'],['investigation','Investigate'],['all','All actions']].map(([id,t])=>`<button class="btn small ${filter===id?'selected':''}" data-act="filter" data-id="${id}">${t}</button>`).join('')}<button class="btn small subtle" data-act="tab" data-id="telemetry">⌕ Search telemetry ↗</button></div>
 <div class="action-list compact-actions">${shown.length?shown.map(a=>`<div class="card action ${a.done?'done':''} ${a.locked?'locked':''}"><div class="row"><div class="micro">${$esc(a.cat.toUpperCase())}</div>${pill(a.source==='Response'?'External response':a.source==='Business'?'Operations':'NetWitness '+a.source)}</div><h3>${$esc(a.title)}</h3><p class="tiny">${$esc(a.desc)}</p><div class="action-foot"><span class="tiny muted">${a.done?'✓ Completed':a.locked?'Needs evidence / approval':a.consoleAction?'⌕ Search to gather proof':`D20 · DC ${a.dc} · ${a.time}m`}</span><button class="btn ${a.consoleAction?'':'primary'} small" data-act="${a.consoleAction?'tab':'act'}" data-id="${a.consoleAction?'telemetry':a.id}" ${a.done||a.locked||g.round.ended?'disabled':''}>${a.done?'Done':a.locked?'Locked':a.consoleAction?'Investigate →':'Execute →'}</button></div></div>`).join(''):`<div class="empty-ready"><b>No actions in this view.</b><p>Search for evidence, try another category or open All actions to check prerequisites.</p><button class="btn small" data-act="tab" data-id="telemetry">Go to Investigation →</button></div>`}</div>
 ${ordered.length>shown.length?`<button class="btn full showmore" data-act="more-actions">Show ${ordered.length-shown.length} more actions ↓</button>`:UI.showAllActions&&ordered.length>6?`<button class="btn full showmore" data-act="more-actions">Show fewer ↑</button>`:''}</section>
 <aside class="mission-rail">${objectives()}<div class="panel compact-score"><div class="micro muted">CASE SCORE • LIVE</div><b>${g.round.score}<small> / 100</small></b><p class="tiny muted">Provisional until case ends</p><p class="tiny teal">Closure gate: ${(g.flags||[]).filter(f=>f.solved).length}/2 flags + ${g.hypotheses.filter(h=>h.solved).length}/2 conclusions</p><button class="btn small" data-act="tab" data-id="casebook">Required evidence flags: ${(g.flags||[]).filter(f=>f.solved).length}/2 →</button><button class="btn small" data-act="tab" data-id="casebook">View evidence & conclusions →</button></div><details class="panel collapsible-feed"><summary>Operations feed · last 6</summary><div class="feed-list">${g.feed.slice(0,6).map(x=>`<div class="feed"><div class="time">T+${$fmt(x.time)}</div>${$esc(x.message)}</div>`).join('')}</div></details></aside></div>`;
}
function objectives(){const obs=UI.game.round.objectives,complete=obs.filter(o=>o.done).length;return `<details class="panel compact-objectives" ${window.innerWidth>800?'open':''}><summary class="objective-summary"><b>Mission objectives</b>${pill(complete+'/'+obs.length)}</summary><div class="objective-progress"><span style="width:${Math.round(complete/Math.max(1,obs.length)*100)}%"></span></div><div class="progress">${obs.map(o=>`<div class="unit"><span class="tick">${o.done?'✓':'○'}</span><span>${$esc(o.title)}</span></div>`).join('')}</div></details>`;}
function progressCard(){return `<div class="panel"><h3>Incident scoreboard</h3><div class="spacing"><div class="micro">Provisional case score</div><div class="summary">${UI.game.round.score} <span class="muted" style="font-size:13px">/ 100</span></div><p class="tiny">Provisional points count toward the live rank. Finalized results are locked when the round ends.</p></div></div>`;}
function feed(){return `<div class="panel"><h3>Operations feed</h3><div class="spacing">${UI.game.feed.slice(0,6).map(x=>`<div class="feed"><div class="time">T+${$fmt(x.time)}</div>${$esc(x.message)}</div>`).join('')}</div></div>`;}
function nextScreen(){const p=UI.player;if(!p)return '';
return `<div class="panel"><div class="kicker">MISSION PROGRESSION</div><h2 class="spacing">${p.finished?'Competition completed!':'Scenario complete'}</h2><p class="spacing">${p.finished?'You finished all four incidents. Your final ranking is shown below.':'Your score has been submitted. Each scenario can be played only once. Continue to the next incident when ready.'}</p><div class="grid3 spacing">${p.rounds.map((r,i)=>`<div class="card"><div class="micro">ROUND ${i+1}</div><h3 class="spacing">${STAGES[i][2]}</h3><p>${status(r.status)}</p><div class="summary spacing">${r.score??'—'}</div></div>`).join('')}</div><div class="row spacing"><div><div class="micro">Combined score</div><div class="summary">${p.total} / 400</div></div>${p.finished?`<button class="btn primary" data-act="tab" data-id="leaderboard">View final leaderboard →</button>`:`<button class="btn primary" data-act="next">Start next scenario →</button>`}</div></div>${UI.reports.some(Boolean)?`<div class="panel spacing next-review"><h3>Mission learning review</h3><p class="tiny muted">Review what went well, what failed, attacker escalations and recommended response practices before starting the next scenario.</p>${UI.reports.map((r,i)=>r?`<button class="btn small spacing" data-act="review" data-id="${i}">Review ${$esc(STAGES[i][2])} · ${r.score}/100 →</button>`:'').join('')}</div>`:''}<div class="panel spacing"><h3>Live ranking</h3>${boardRows(12)}</div>`;}
function hexDump(raw){const bytes=String(raw||'').trim().split(/\s+/).filter(x=>/^[0-9a-fA-F]{2}$/.test(x));const lines=[];for(let i=0;i<bytes.length;i+=16){const cells=bytes.slice(i,i+16),ascii=cells.map(x=>{const n=parseInt(x,16);return n>=32&&n<127?String.fromCharCode(n):'.'}).join('');lines.push(i.toString(16).padStart(4,'0')+'  '+cells.map(x=>x.toUpperCase()).join(' ').padEnd(47,' ')+'  '+ascii)}return lines.join('\n');}
function packetFrames(x){if(!x?.packet)return '';return `<div class="packets"><div class="row"><div><b>Reconstructed network session</b><div class="tiny muted">${$esc(x.packet.summary||'')}</div></div>${pill(x.packet.visibility||'Captured bytes',x.packet.visibility?.toLowerCase().includes('encrypt')?'warn':'live')}</div>${(x.packet.frames||[]).map((f,i)=>`<div class="packet-frame"><div class="row"><span class="micro teal">FRAME ${i+1} · ${$esc(f.protocol)}</span><b class="tiny">${$esc(f.name)}</b></div><div class="micro spacing">${x.packet.visibility?.includes('Decoded')?'Reassembled application bytes · HEX + ASCII':'Wire bytes · HEX + ASCII'}</div><pre class="hexdump">${$esc(hexDump(f.hex))}</pre><div class="micro spacing">Decoded protocol fields</div><div class="decode-grid">${Object.entries(f.decoded||{}).map(([k,v])=>`<div><span class="tiny muted">${$esc(k)}</span><b class="mono">${$esc(v)}</b></div>`).join('')}</div>${f.notes&&!/visibility limit|cannot be decrypted|cannot be reconstructed|encrypted session/i.test(f.notes)?`<p class="tiny spacing">${$esc(f.notes)}</p>`:''}</div>`).join('')}</div>`;}
function logDetails(x){if(!x?.log)return '';return `<div class="endpoint-context"><div class="row"><b>Raw log event</b>${pill(x.log.format||'Event log','live')}</div><div class="micro spacing">Original event fields and message</div><pre class="command-line">${$esc(x.log.raw)}</pre></div>`;}
function endpointDetails(x){if(!x?.endpoint)return '';const e=x.endpoint;return `<div class="endpoint-context"><div class="row"><b>Full endpoint process context</b>${pill('Simulated endpoint telemetry','live')}</div><div class="micro spacing">Process command line and all captured parameters</div><pre class="command-line">${$esc(e.commandLine)}</pre><div class="micro spacing">Parent command line</div><pre class="command-line secondary">${$esc(e.parentCommandLine)}</pre><div class="decode-grid spacing"><div><span class="tiny muted">Executable image</span><b class="mono">${$esc(e.image)}</b></div><div><span class="tiny muted">Process / parent PID</span><b class="mono">${$esc(e.pid)} / ${$esc(e.ppid)}</b></div><div><span class="tiny muted">Working directory</span><b class="mono">${$esc(e.cwd)}</b></div></div><p class="tiny spacing">${$esc(e.notes||'')}</p></div>`;}
function evidenceGuide(g){const guide=g.guide;if(!guide)return '';const total=guide.milestones.length,completed=guide.milestones.filter(m=>m.complete).length;return `<div class="guide panel compact-guide"><div class="guide-head"><div><div class="micro teal">EVIDENCE PLAN · ${completed}/${total} CORRELATED</div><b>Unsure where to investigate?</b><p class="tiny muted">Open the guide for Logs / Network / Endpoint hints.</p></div><button class="btn small" data-act="guide-toggle" aria-expanded="${UI.guideOpen}">${UI.guideOpen?'Hide guide ↑':'Show guide ↓'}</button></div>${UI.guideOpen?`<div class="guide-body"><p class="tiny">${$esc(guide.brief)}</p><div class="guide-grid spacing">${guide.milestones.map((m,i)=>`<div class="guide-card ${m.complete?'done':''}"><div class="row"><span class="micro teal">GOAL ${i+1}</span>${pill(m.complete?'✓ Correlated':m.found?'Partial '+m.found+'/'+m.total:'Open',m.complete?'live':m.found?'warn':'')}</div><h4>${$esc(m.title)}</h4><p class="tiny muted">${$esc(m.goal)}</p><div class="chips">${m.sources.map(src=>`<button class="source-chip" data-act="guide-source" data-id="${$esc(src)}">${$esc(src)} ↗</button>`).join('')}</div><details><summary class="tiny muted">Why these sources?</summary><p class="tiny">${$esc(m.why)}</p></details></div>`).join('')}</div></div>`:''}</div>`;}
function consoleTab(){const g=UI.game;if(!g)return nextScreen();const records=g.console.results||[],tips=g.guide?.pivotIdeas?.[UI.source]||[];
 return `<div class="investigation-workspace"><div class="compact-page-header"><div><div class="kicker">SIMULATED NETWITNESS</div><h2>Investigation</h2><p class="tiny muted">Search events and inspect raw logs, packet payloads or full process commands. Searches cost 2 incident minutes.</p></div>${pill((g.console.searched||[]).length+' searches')}</div>
 ${evidenceGuide(g)}<div class="panel console-panel"><div class="console-top"><div class="tabs">${['Logs','Network','Endpoint'].map(x=>`<button class="btn small ${UI.source===x?'selected':''}" data-act="source" data-id="${x}">▣ ${x}</button>`).join('')}</div><div class="tiny muted">${UI.source==='Network'?'Packet bytes in Inspect':UI.source==='Endpoint'?'Full commands in Inspect':'Full raw log in Inspect'}</div></div>
 <form id="query-form" class="query compact-query"><input class="input" name="query" id="query" value="${$esc(UI.query)}" placeholder="${UI.source==='Network'?'service = \'smb\'':UI.source==='Endpoint'?'process ~ \'powershell\'':"user.dst = 'svc_backup'"}" required maxlength="180" aria-label="Search expression"><button class="btn primary" type="submit" ${g.round.ended?'disabled':''}>⌕ Search +2m</button></form>
 <div class="compact-pivots"><span class="micro muted">PIVOT IDEAS</span><div class="pivot-scroll">${tips.map(t=>`<button class="pivot-chip" data-act="pivot" data-query="${$esc(t)}" title="Populate expression">${$esc(t)}</button>`).join('')}</div></div>
 ${g.console.notice?`<div class="alert compact-notice">${$esc(g.console.notice)}</div>`:''}<div class="results-title"><h3>${records.length} matching records</h3><span class="tiny muted">Click Inspect for complete forensic detail</span></div>
 <div class="events bounded-results"><table class="event-table"><thead><tr><th>Time</th><th>Sensor</th><th>Related indicators</th><th>Activity</th><th></th></tr></thead><tbody>${records.length?records.map(r=>`<tr><td class="mono">${$esc(r.time)}</td><td>${$esc(r.host)}</td><td class="mono indicator-cell">${$esc(r.fields['ip.src']||r.fields['user.dst']||r.fields.process||'—')} → ${$esc(r.fields['ip.dst']||r.fields['alias.host']||r.fields.service||'—')}</td><td><div>${$esc(r.fields.action||r.fields.service||'event')}</div>${r.endpoint?`<div class="tiny muted truncate-command" title="Open Inspect for full command">${$esc(r.endpoint.commandLine)}</div>`:''}${r.packet?'<span class="tiny teal">Packet bytes available</span>':''}</td><td><button class="btn small" data-act="inspect" data-id="${$esc(r.id)}">${r.reviewed?'Review':'Inspect →'}</button></td></tr>`).join(''):'<tr><td colspan="5" class="muted">No records loaded. Choose a Pivot Idea or enter a filter.</td></tr>'}</tbody></table></div>
 <div class="console-foot tiny muted">Synthetic training records. Selected HTTPS sessions include decoded HTTP from a configured TLS inspection point. <button class="text-link" data-act="guide-toggle">${UI.guideOpen?'Hide':'Show'} evidence hints</button></div></div></div>`;
}
function evidence(){const arr=UI.game?.evidence||[];return `<div class="panel"><div class="title"><div><h2>Evidence locker</h2><p>Exhibits collected from simulated investigation records.</p></div>${pill(arr.length+' secured')}</div><div class="grid3 spacing">${arr.map(e=>`<div class="exhibit"><div class="micro teal">${$esc(e.source)} · ${$esc(e.asset)}</div><h3 class="spacing">${$esc(e.title)}</h3><p class="tiny spacing">${$esc(e.summary)}</p><button class="btn small spacing" data-act="exhibit" data-id="${e.id}">Inspect exhibit →</button></div>`).join('')||'<p>No exhibits collected yet.</p>'}</div></div>`;}
function ctfFlags(){const g=UI.game;if(!g)return nextScreen();const flags=g.flags||[];const found=flags.filter(f=>f.solved).length;return `<div class="panel"><div class="title"><div><div class="kicker">MANDATORY FORENSIC CHECKPOINT</div><h2>Evidence flags</h2><p>Both flags are mandatory to unlock verified mission closure. They are worth up to 7 points together within the existing 100-point scenario score, not extra bonus points. Inspect the matching record, extract its exact artifact, then enter the value. Wrong answers consume 3 simulated minutes; correct answers consume 1 minute.</p></div>${pill(found+'/'+flags.length+' recovered',found===flags.length?'live':'')}</div><div class="flag-grid spacing">${flags.map((f,i)=>`<div class="card flag-card ${f.solved?'solved':''}"><div class="row"><span class="micro teal">FLAG ${i+1} · ${$esc(f.source)}</span>${pill(f.solved?'✓ Verified':'Awaiting evidence',f.solved?'live':'')}</div><h3>${$esc(f.title)}</h3><p class="tiny">${$esc(f.prompt)}</p>${!f.solved?`<div class="row spacing"><input class="input" id="flag-${f.id}" placeholder="Enter value from inspected record" autocomplete="off" maxlength="140" aria-label="Flag ${$esc(f.title)}"/><button class="btn primary small" data-act="flag" data-id="${$esc(f.id)}" ${g.round.ended?'disabled':''}>Submit (+1m)</button></div><details class="spacing"><summary class="tiny muted">Need a hint?</summary><p class="tiny">${$esc(f.hint)}</p></details><button class="text-link spacing" data-act="guide-source" data-id="${$esc(f.source)}">Open ${$esc(f.source)} investigation →</button>${f.attempts?`<div class="tiny muted spacing">Attempts: ${f.attempts}</div>`:''}`:'<p class="tiny teal spacing">Flag accepted by the competition server.</p>'}</div>`).join('')}</div><div class="alert spacing">MISSION GATE: 2/2 verified flags + at least 2 evidence-supported conclusions are required before final verification can close the case. Flags provide up to 7 of the existing 100 points, not additional points.</div></div>`;}

function hypotheses(){const g=UI.game;if(!g)return nextScreen();return `<div class="panel"><div class="title"><div><h2>Investigation conclusions</h2><p>Substantiate at least two conclusions with source evidence to close an incident.</p></div>${pill(g.hypotheses.filter(x=>x.solved).length+'/3')}</div><div class="stack spacing">${g.hypotheses.map(q=>{const ready=q.requirements.every(x=>x.found);return `<div class="card question"><div class="row"><div class="micro teal">ANALYST CONCLUSION</div>${pill(q.solved?'✓ Substantiated':ready?'Ready':'Missing evidence',q.solved?'live':ready?'':'warn')}</div><h3>${$esc(q.question)}</h3><p class="tiny">Supporting exhibits: ${q.requirements.map(r=>$esc(r.title)+(r.found?' ✓':' ○')).join(' · ')}</p><details class="conclusion-hint"><summary class="tiny muted">Need a reasoning hint?</summary><div class="tiny">${$esc(q.hint||'Compare the supporting exhibits, their sources, and the event sequence before choosing.')}</div></details>${q.solved?`<div class="alert">${$esc(q.reason)}</div>`:`<div><label class="label" for="answer-${q.id}">Your assessment</label><select id="answer-${q.id}" class="select" data-answer="${q.id}"><option value="">Select an assessment…</option>${q.options.map((o,i)=>`<option value="${i}" ${UI.answer[q.id]===String(i)?'selected':''}>${$esc(o)}</option>`).join('')}</select></div><button class="btn primary small" data-act="hypothesis" data-id="${q.id}" ${!ready||g.round.ended?'disabled':''}>Submit evidence-backed conclusion (+3m)</button>`}</div>`}).join('')}</div></div>`;}
function debrief(){const g=UI.game;const available=UI.reports.map((r,i)=>r?i:-1).filter(i=>i>=0);if(!g&&available.length===0)return nextScreen();const selected=available.includes(UI.reviewStage)?UI.reviewStage:available.at(-1);const report=selected!==undefined&&selected!==null?UI.reports[selected]:null;if(!g&&report)return reportView(report);if(g&&UI.reviewStage!==null&&report)return reportView(report);return `<div class="panel"><div class="title"><div><h2>After-action review</h2><p>${g.round.ended?'The final result was calculated on the server.':'This score is provisional until technical closure.'}</p></div>${pill(g.round.assessment||'active')}</div><div class="grid3 spacing"><div class="card"><div class="micro">Mission score</div><div class="summary">${g.round.score}/100</div></div><div class="card"><div class="micro">Business health</div><div class="summary">${g.round.health}%</div></div><div class="card"><div class="micro">Exposure risk</div><div class="summary amber">${g.round.exposure}%</div></div></div><details class="history-details spacing"><summary>Incident chronicle · ${g.chronicle.length} events</summary>${g.chronicle.slice().reverse().map(x=>`<div class="feed"><span class="time">T+${$fmt(x.time)} · ${$esc(x.type||'event')}</span><b style="display:block">${$esc(x.title)}</b>${$esc(x.desc||'')}</div>`).join('')}</details></div>`;}
function learningItems(items,kind){return `<div class="learning-column"><div class="micro ${kind==='good'?'teal':'amber'}">${kind==='good'?'WHAT WENT WELL':'WHAT NEEDS IMPROVEMENT'} · ${items.length}</div>${items.length?items.map(x=>`<div class="learning-item ${kind}"><b>${$esc(x.title)}</b><p class="tiny muted">${$esc(x.detail)}</p></div>`).join(''):'<p class="tiny muted spacing">No items in this category.</p>'}</div>`;}
function reportView(r){const l=r.learning;
return `<div class="panel"><div class="title"><div><div class="kicker">THE WAR ROOM / AFTER-ACTION REVIEW</div><h2>${$esc(r.title)}</h2><p>${$esc(r.assessment)} · Technical outcome: ${$esc(r.reason)}</p></div>${pill('Final '+r.score+'/100','live')}</div>${UI.player?.active===-1&&!UI.player?.finished?`<button class="btn primary spacing" data-act="next">Start next scenario →</button>`:''}<div class="chips spacing">${UI.reports.map((report,i)=>report?`<button class="btn small ${UI.reviewStage===i?'selected':''}" data-act="review" data-id="${i}">${$esc(STAGES[i][2])} · ${report.score}</button>`:'').join('')}</div>
${l?`<div class="learning-summary spacing"><div class="micro teal">ASSESSMENT</div><h3>${$esc(l.overall)}</h3><p class="tiny spacing">${$esc(l.focus)}</p></div>`:''}
<div class="grid3 spacing"><div class="card"><div class="micro">Final score</div><div class="summary">${r.score}/100</div></div><div class="card"><div class="micro">Incident clock</div><div class="summary">${$fmt(r.clock)}</div></div><div class="card"><div class="micro">Business health</div><div class="summary">${r.health}%</div></div></div>
${l?`<div class="learning-grid spacing">${learningItems(l.whatWentWell||[],'good')}${learningItems(l.needsImprovement||[],'bad')}</div><div class="learning-summary spacing"><div class="micro teal">RECOMMENDATIONS</div><ol class="recommendations">${(l.recommendations||[]).map(t=>`<li>${$esc(t)}</li>`).join('')}</ol></div><div class="learning-summary spacing"><h3>Attacker timeline & missed containment windows</h3><p class="tiny muted">${$esc(l.attacker?.overview||'')}</p><p class="spacing tiny"><b>Containment:</b> ${l.attacker?.containedAt==null?'Incomplete':'T+'+$fmt(l.attacker.containedAt)} · <b>Target:</b> T+${$fmt(l.attacker?.target||0)}</p><p class="tiny">${$esc(l.attacker?.notes||'')}</p>${(l.attacker?.occurred||[]).map(e=>`<div class="learning-item bad"><b>T+${$fmt(e.minute)} · ${$esc(e.title)}</b><p class="tiny muted">Damaging event occurred before effective defenses. Scoring penalty ${e.points} points; maximum case score ${e.cap}.</p></div>`).join('')}${(l.attacker?.avoided||[]).length?`<details class="history-details spacing"><summary>Prevented attacker steps (${l.attacker.avoided.length})</summary>${l.attacker.avoided.map(x=>`<p class="tiny spacing">T+${$fmt(x.time)} · ${$esc(x.title)}</p>`).join('')}</details>`:''}</div>`:''}
<details class="history-details spacing"><summary>Score calculation and caps</summary><div class="grid3 spacing">${Object.entries(r.scoreBreakdown||{}).map(([k,v])=>`<div class="card"><div class="micro">${$esc(k)}</div><h3 class="spacing">${v}</h3></div>`).join('')}</div>${r.caps?.length?`<div class="alert warn spacing"><b>Outcome limits:</b> ${r.caps.map(x=>$esc(x.reason)).join('; ')}</div>`:''}</details>
<details class="history-details spacing"><summary>Mission objectives</summary><div class="progress spacing">${(r.objectives||[]).map(x=>`<div class="unit"><span class="tick">${x.done?'✓':'○'}</span>${$esc(x.title)}</div>`).join('')}</div></details><details class="history-details spacing"><summary>Full incident chronicle · ${(r.chronicle||[]).length} events</summary>${(r.chronicle||[]).slice().reverse().map(x=>`<div class="feed"><div class="time">T+${$fmt(x.time)}</div><b>${$esc(x.title)}</b><div class="tiny muted">${$esc(x.desc||'')}</div></div>`).join('')}</details></div>`;}

function casebook(){const g=UI.game,available=UI.reports.some(Boolean);if(!g&&!available)return nextScreen();return `<div class="casebook-workspace"><div class="compact-page-header"><div><div class="kicker">DOCUMENT THE INVESTIGATION</div><h2>Casebook</h2><p class="tiny muted">Forensic CTF flags, exhibits, supported conclusions and response results in one place.</p></div></div><div class="subtabs">${[['flags','CTF flags'],['conclusions','Conclusions'],['evidence','Exhibits'],['review','After-action']].map(([id,title])=>`<button class="btn small ${UI.caseTab===id?'selected':''}" data-act="case-tab" data-id="${id}">${title}${id==='evidence'&&g?' · '+g.evidence.length:''}</button>`).join('')}</div>${UI.caseTab==='flags'?(g?ctfFlags():debrief()):UI.caseTab==='evidence'?(g?evidence():reportCaseEvidence()):UI.caseTab==='review'?debrief():(g?hypotheses():debrief())}</div>`;}
function reportCaseEvidence(){const all=UI.reports.filter(Boolean);return `<div class="panel"><h3>Completed cases</h3><p class="tiny muted">These missions are finalized. View their after-action reports for evidence and outcomes.</p>${all.map((r,i)=>`<button class="btn small spacing" data-act="case-tab" data-id="review">${$esc(r.title)} · ${r.score}/100</button>`).join('')}</div>`;}
function adminOverview(){const d=UI.adminData;if(!d)return '';
 const players=d.players.filter(p=>UI.adminFilter==='all'||(UI.adminFilter==='finished'?p.completed===4:UI.adminFilter==='active'?p.activeStage!==null:p.completed===0));
 const sorted=players.slice().sort((a,b)=>UI.adminSort==='name'?a.name.localeCompare(b.name):UI.adminSort==='recent'?String(b.lastActivity||'').localeCompare(String(a.lastActivity||'')):a.rank-b.rank);
 return `<div class="panel spacing"><div class="title"><div><div class="kicker">ADMINISTRATOR / LIVE COMPETITION</div><h2>All players overview</h2><p>Restricted player progress, scores, evidence flags and incident outcomes. Refresh as required.</p></div><button class="btn small" data-act="admin-refresh">↻ Refresh</button></div><div class="grid3 spacing">${[['Players',d.summary.registered],['Playing',d.summary.active],['Finished',d.summary.finished],['Completed rounds',d.summary.completedRounds]].map(([k,v])=>`<div class="card"><div class="micro">${k}</div><div class="summary">${v}</div></div>`).join('')}</div><div class="row spacing"><div class="quick-nav">${[['all','All'],['active','Playing'],['finished','Finished'],['new','Not finished a round']].map(([id,label])=>`<button class="btn small ${UI.adminFilter===id?'selected':''}" data-act="admin-filter" data-id="${id}">${label}</button>`).join('')}</div><label class="tiny muted">Sort <select class="select admin-sort" data-admin-sort><option value="rank" ${UI.adminSort==='rank'?'selected':''}>Rank</option><option value="name" ${UI.adminSort==='name'?'selected':''}>Name</option><option value="recent" ${UI.adminSort==='recent'?'selected':''}>Last activity</option></select></label></div><div class="leaderboard"><table><thead><tr><th>#</th><th>Player</th><th>Progress</th>${STAGES.map(x=>`<th>${$esc(x[1])}</th>`).join('')}<th>Live / 400</th><th>Current case</th><th>Learning issues</th></tr></thead><tbody>${sorted.map(p=>`<tr><td>${p.rank}</td><td><b>${$esc(p.name)}</b><div class="tiny muted">Last: ${$esc(p.lastActivity?.slice(0,16)||'—')}</div></td><td>${p.completed}/4</td>${p.stages.map(r=>`<td class="mono">${r.status==='complete'?$esc(r.score):r.status==='active'?'●':'—'}</td>`).join('')}<td><b>${p.total}</b>${p.provisional?`<div class="tiny muted">+${p.provisional} provisional</div>`:''}</td><td class="tiny">${p.activeDetails?`T+${$fmt(p.activeDetails.clock)} · ${p.activeDetails.flagsSolved}/2 flags · ${p.activeDetails.conclusions}/3 conclusions`:p.completed===4?'Finished':'Not started'}</td><td class="tiny">${$esc((p.learningIssues||[]).slice(0,2).join(' · ')||'—')}</td></tr>`).join('')||'<tr><td colspan="10">No matching players</td></tr>'}</tbody></table></div><p class="tiny muted spacing">Access is password-protected. Scores and progress are loaded from the authoritative competition server, never from another player’s browser.</p></div>`;}
function admin(){return `<div class="panel admin-box"><div class="kicker">RESTRICTED • ADMINISTRATOR</div><h2 class="spacing">Competition dashboard</h2><p class="spacing">Authenticate to inspect all players, progress and results. The reset control below permanently clears the current tournament.</p><div class="alert spacing">Use the installation-specific password in <code>data/admin-password.txt</code> (or your configured <code>ADMIN_PASSWORD</code>). Do not share this password with players.</div><form id="admin-login-form" class="form spacing"><div><label class="label" for="admin-password">Administrator password</label><input id="admin-password" type="password" class="input" autocomplete="off" required value="${$esc(UI.adminPassword)}"></div><button class="btn primary" type="submit">${UI.adminData?'Refresh player overview':'Open admin dashboard'} →</button></form></div>${adminOverview()}<details class="panel spacing admin-reset" ${UI.adminData?'':'disabled'}><summary class="danger">Danger zone · Reset entire competition</summary><p class="tiny spacing">Reset removes all player sessions, attempts, scores and rankings. This cannot be undone.</p><form id="reset-form" class="form spacing"><div><label class="label" for="reset-confirm">Type RESET EVERYTHING</label><input id="reset-confirm" class="input" required autocomplete="off" placeholder="RESET EVERYTHING"></div><button class="btn danger" type="submit">Reset entire tournament</button></form></details>`;}

function boardPage(){return `<div class="panel"><div class="title"><div><div class="kicker">LIVE COMPETITION</div><h2>Global leaderboard</h2><p>Players compete across all four incidents. Combined finalized and provisional scores from active missions, recalculated by the server after each move.</p></div>${pill((UI.board.players||0)+' joined','live')}</div><div id="board-table">${boardRows()}</div></div>`;}
function app(){if(!UI.player){if(UI.tab==='admin')return `<div class="landing"><div class="row"><div class="brand"><div class="brand-icon">✥</div><b>THE WAR ROOM / ADMIN</b></div><button class="btn" data-act="reload">← Back</button></div>${UI.error?`<div class="alert error spacing">${$esc(UI.error)}</div>`:''}<div class="spacing">${admin()}</div></div>`;return home();}
 const page=UI.player.active<0&&UI.tab==='operations'?nextScreen():UI.tab==='telemetry'?consoleTab():['evidence','hypotheses','debrief','casebook'].includes(UI.tab)?casebook():UI.tab==='leaderboard'?boardPage():UI.tab==='admin'?admin():missions();
 const match=UI.tab==='evidence'||UI.tab==='hypotheses'||UI.tab==='debrief'?'casebook':UI.tab;
 return `<div class="arena">${sidebar()}<main class="layout"><header class="topbar compact-topbar"><div class="row"><span class="pill live">● Live tournament</span><span class="muted tiny">${$esc(UI.player.name)} · ${UI.player.completed}/4 missions</span></div><div class="row">${pill((UI.player.liveTotal??UI.player.total)+' / 400 pts')}${pill('Rank #'+(UI.player.rank||'—'))}<button class="btn small top-admin" data-act="tab" data-id="admin" title="Administrator settings" aria-label="Administrator settings">⚙</button></div></header><section class="content compact-content">${UI.error?`<div class="alert error">${$esc(UI.error)}</div>`:''}${UI.notice?`<div class="alert">${$esc(UI.notice)}</div>`:''}${UI.game&&match!=='leaderboard'&&match!=='admin'&&UI.player.active>=0?metrics():''}${page}<footer class="footer row"><span>V5 NetWitness simulation · All scores server-calculated · No live NetWitness access</span><span>The War Room: Incident Response</span></footer></section></main></div>${UI.modal?dialog():''}`;
}
function dialog(){const m=UI.modal;if(m.type==='inspect'){const x=m.row;return `<div class="overlay"><div class="dialog forensic-dialog"><div class="row"><div><div class="kicker">SIMULATED ${$esc(x.source.toUpperCase())} EVENT</div><h2 class="spacing">${$esc(x.host)} · ${$esc(x.time)}</h2></div><button class="btn small" data-act="modal-close">✕</button></div><p class="spacing">${$esc(x.detail)}</p>${x.packet?`<div class="spacing">${packetFrames(x)}</div>`:''}${x.endpoint?`<div class="spacing">${endpointDetails(x)}</div>`:''}${x.log?`<div class="spacing">${logDetails(x)}</div>`:''}<div class="card spacing"><div class="micro">Record fields</div>${Object.entries(x.fields||{}).map(([k,v])=>`<div class="field-row"><span class="mono teal">${$esc(k)}</span><span class="mono">${$esc(v)}</span></div>`).join('')}</div><div class="alert spacing">Reviewing a record costs one in-game minute the first time. Only relevant records become forensic exhibits.</div><div class="dialog-actions"><button class="btn" data-act="modal-close">Cancel</button><button class="btn primary" data-act="collect" data-id="${x.id}">${x.reviewed?'Review again':'Collect / review record'}</button></div></div></div>`;}
if(m.type==='act'){const a=m.action;return `<div class="overlay"><div class="dialog"><div class="row"><div><div class="kicker">${$esc(a.cat.toUpperCase())} / ${$esc(a.source)}</div><h2 class="spacing">${$esc(a.title)}</h2></div><button class="btn small" data-act="modal-close">✕</button></div><p class="spacing">${$esc(a.desc)}</p>${a.tool?`<div class="alert spacing"><b>External enforcement:</b> ${$esc(a.tool)}. NetWitness is used for investigation, not blocking.</div>`:''}<div class="grid3 spacing"><div class="card"><div class="micro">Skill</div><h3>DC ${a.dc}</h3></div><div class="card"><div class="micro">Time</div><h3>${a.time} min</h3></div><div class="card"><div class="micro">Dice</div><h3>D20</h3></div></div><div class="alert spacing">Every competitor uses the same response proficiency and server-generated D20 rolls. No specialist selection is needed.</div>${a.cat==='risky'?'<div class="alert warn spacing">A high dice roll cannot make an unsafe decision safe. This choice can severely reduce your score.</div>':''}<div class="dialog-actions"><button class="btn" data-act="modal-close">Cancel</button><button class="btn primary" data-act="act-confirm" data-id="${a.id}">Roll and execute →</button></div></div></div>`;}
if(m.type==='exhibit'){const e=m.evidence;return `<div class="overlay"><div class="dialog"><div class="row"><div><div class="kicker">FORENSIC EXHIBIT</div><h2 class="spacing">${$esc(e.title)}</h2></div><button class="btn small" data-act="modal-close">✕</button></div><p class="spacing">${$esc(e.summary)}</p><pre class="spacing" style="white-space:pre-wrap;overflow-wrap:anywhere;background:#091827;padding:12px;border-radius:8px">${$esc(e.raw||'')}</pre><div class="dialog-actions"><button class="btn primary" data-act="modal-close">Close</button></div></div></div>`;}
if(m.type==='result'){const f=m.feedback;return `<div class="overlay"><div class="dialog"><div class="kicker">D20 / SERVER-VERIFIED RESOLUTION</div><h2 class="spacing">${$esc(f.title||'Response result')}</h2>${pill(f.hazardous?'UNSAFE DECISION':f.verdict?.toUpperCase()||'RESULT',f.hazardous?'fail':f.verdict==='success'?'live':'warn')}<div class="summary spacing">🎲 ${f.die??'—'}</div><p>Rolls ${Array.isArray(f.dice)?f.dice.join(' / '):''} · Total ${f.total??'—'} against DC ${f.dc??'—'}</p><div class="alert spacing">The server applied ${f.verdict==='success'?'successful':f.verdict==='partial'?'partial':'unsuccessful'} resolution, +${f.timeCost||0} in-game minutes, and updated the incident state.</div>${m.coaching?`<div class="learning-note ${m.coaching.kind==='error'?'unsafe':'educational'} spacing"><b>${$esc(m.coaching.title)}</b><p class="tiny spacing">${$esc(m.coaching.why)}</p><div class="tiny"><b>Learning point:</b> ${$esc(m.coaching.better)}</div></div>`:''}${m.escalations?.length?`<div class="learning-note unsafe spacing"><b>Attacker escalation during this action</b>${m.escalations.map(x=>`<p class="tiny spacing">T+${$fmt(x.time)} · ${$esc(x.title)}. This caused incident damage and may cap the final score at ${x.cap}.</p>`).join('')}</div>`:''}<div class="dialog-actions"><button class="btn primary" data-act="modal-close">Continue →</button></div></div></div>`;}
return '';}
function render(){root.innerHTML=app();}
async function move(body){if(UI.busy)return;UI.busy=true;UI.error='';try{const response=await request('/api/action',body);updateMe(response);UI.notice=body.type==='flag'?(response.feedback?.correct?'Flag accepted. The artifact is verified. (+1 simulated minute)':'Flag not accepted. Reinspect the relevant record. (+3 simulated minutes)'):body.type==='hypothesis'?(response.feedback?.coaching||'Conclusion recorded.'):'';if(response.escalations?.length)UI.notice+=' ATTACKER ESCALATION: '+response.escalations.map(x=>x.title+' at T+'+$fmt(x.time)).join('; ')+'. The loss affects final scoring.';}catch(e){UI.error=e.message;}finally{UI.busy=false;render();}}
async function join(username){if(UI.busy)return;UI.busy=true;UI.error='';try{const x=await request('/api/join',{username});updateMe(x);UI.tab='operations';UI.filter='ready';}catch(e){UI.error=e.message;}finally{UI.busy=false;render();}}
async function next(){if(UI.busy)return;UI.busy=true;UI.error='';try{const x=await request('/api/next',{});updateMe(x);UI.tab='operations';UI.reviewStage=null;UI.filter='ready';UI.showAllActions=false;UI.showMissionBrief=true;}catch(e){UI.error=e.message;}finally{UI.busy=false;render();}}
async function loadAdmin(password){if(UI.busy)return;UI.busy=true;UI.error='';try{const result=await request('/api/admin/overview',{password});UI.adminPassword=password;UI.adminData=result;UI.notice='Admin overview refreshed at '+result.generatedAt.slice(11,19)+' UTC';}catch(e){UI.error=e.message;UI.adminData=null;}finally{UI.busy=false;render();}}
async function reset(password,phrase){if(UI.busy)return;UI.busy=true;UI.error='';try{await request('/api/admin/reset',{password,confirm:phrase});UI.notice='Tournament reset. All players, scores, and sessions were invalidated.';UI.player=null;UI.game=null;UI.adminData=null;UI.adminPassword='';UI.tab='operations';UI.board=await request('/api/board');}catch(e){UI.error=e.message;}finally{UI.busy=false;render();}}
root.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='join-form')join(e.target.elements.username.value.trim());if(e.target.id==='query-form'){const value=e.target.elements.query.value.trim();UI.query=value;move({type:'query',source:UI.source,query:value});}if(e.target.id==='admin-login-form')loadAdmin(e.target.querySelector('#admin-password').value);if(e.target.id==='reset-form')reset(UI.adminPassword,e.target.querySelector('#reset-confirm').value);});
root.addEventListener('input',e=>{if(e.target.id==='query')UI.query=e.target.value;});
root.addEventListener('change',e=>{if(e.target.matches('[data-admin-sort]')){UI.adminSort=e.target.value;render();return;}if(e.target.matches('[data-answer]'))UI.answer[e.target.dataset.answer]=e.target.value;});
root.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b)return;const id=b.dataset.id,action=b.dataset.act;if(UI.busy&& !['modal-close'].includes(action))return;
 if(action==='reload'){load();return}if(action==='tab'){UI.tab=id;if(id==='casebook')UI.caseTab='flags';if(id==='debrief'){UI.caseTab='review';UI.reviewStage=null;}if(id==='evidence')UI.caseTab='evidence';if(id==='hypotheses')UI.caseTab='conclusions';UI.error='';UI.notice='';render();return}if(action==='case-tab'){UI.caseTab=id;UI.tab='casebook';render();return}if(action==='more-actions'){UI.showAllActions=!UI.showAllActions;render();return}if(action==='brief-toggle'){UI.showMissionBrief=!UI.showMissionBrief;render();return}if(action==='admin'){UI.tab='admin';UI.modal=null;UI.error='';render();return}
 if(action==='admin-refresh'){loadAdmin(UI.adminPassword);return}if(action==='admin-filter'){UI.adminFilter=id;render();return}if(action==='next'){next();return}if(action==='review'){UI.reviewStage=Number(id);UI.tab='casebook';UI.caseTab='review';render();return}if(action==='filter'){UI.filter=id;UI.showAllActions=false;render();return}if(action==='source'){UI.source=id;UI.query='';render();return}if(action==='pivot'){UI.query=b.dataset.query||'';const field=root.querySelector('#query');if(field){field.value=UI.query;field.focus();field.setSelectionRange(field.value.length,field.value.length);}return}if(action==='guide-toggle'){UI.guideOpen=!UI.guideOpen;render();return}if(action==='guide-source'){UI.tab='telemetry';UI.source=id;UI.query=UI.game?.guide?.pivotIdeas?.[id]?.[0]||'';render();root.querySelector('#query')?.focus();return}
 if(action==='inspect'){const row=UI.game?.console.results.find(r=>r.id===id);if(row)UI.modal={type:'inspect',row};render();return}
 if(action==='exhibit'){const ex=UI.game?.evidence.find(x=>x.id===id);if(ex)UI.modal={type:'exhibit',evidence:ex};render();return}
 if(action==='act'){const a=UI.game?.actions.find(x=>x.id===id);if(a){UI.modal={type:'act',action:a};}render();return}
 if(action==='modal-close'){const finishedRound=UI.modal?.type==='result'&&!UI.game&&UI.reports.some(Boolean);UI.modal=null;if(finishedRound){UI.tab='casebook';UI.caseTab='review';UI.reviewStage=UI.reports.map((r,i)=>r?i:-1).filter(i=>i>=0).at(-1);}render();return}
 if(action==='collect'){UI.modal=null;await move({type:'collect',id});return}
 if(action==='act-confirm'){UI.modal=null;await move({type:'action',id});return}
 if(action==='flag'){const value=root.querySelector('#flag-'+id)?.value||'';if(!value.trim()){UI.error='Enter the forensic flag value.';render();return}await move({type:'flag',id,value:value.trim()});if(UI.game)UI.caseTab='flags';return}
 if(action==='hypothesis'){const c=root.querySelector('#answer-'+id)?.value;if(c==null||c===''){UI.error='Choose a conclusion first.';render();return}await move({type:'hypothesis',id,choice:Number(c)});return}
});
function connectEvents(){let es;try{es=new EventSource('/api/events',{withCredentials:true});es.addEventListener('board',e=>{try{UI.board=JSON.parse(e.data);if(UI.player){const self=UI.board.leaderboard?.find(x=>x.name===UI.player.name);if(self){UI.player.rank=self.rank;UI.player.liveTotal=self.score;UI.player.provisionalScore=self.provisional;}}if(!UI.player||UI.tab==='leaderboard'){const el=root.querySelector('#board-table');if(el)el.innerHTML=boardRows(UI.tab==='leaderboard'?null:20);}const status=root.querySelectorAll('.pill.live');}catch(err){}});es.addEventListener('reset',()=>{UI.player=null;UI.game=null;UI.modal=null;UI.adminPassword='';UI.adminData=null;UI.tab='operations';UI.error='Administrator reset the tournament. Choose a new username to join the new round.';load();});es.onerror=()=>{};}catch(e){} }
load();connectEvents();
